#!/usr/bin/env bash
set -euo pipefail
# Decomposed binding + retrieval for all 11 final text-study checkpoints, split over GPUs 0-3.
# Each job skips labels already present in outputs/decomposed_eval/.
cd /home/zd25e122/clevr_discrete_diffusion
py=/home/zd25e122/miniconda3/envs/unix/bin/python3.10; out=outputs/decomposed_eval; mkdir -p $out
tmux new-session -d -s clevr_decomp_0 "cd $PWD && exec env CUDA_DEVICE_ORDER=PCI_BUS_ID CUDA_VISIBLE_DEVICES=0 PYTHONUNBUFFERED=1 $py evaluate_decomposed_representations.py --output-dir $out --checkpoint dense_epoch003=outputs/text_dense_diffusion_2m_4e_matched/epoch_003.pt --checkpoint plain_lora_epoch003=outputs/text_lora_diffusion_2m_4e_matched/epoch_003.pt --checkpoint layerwise_gated_hsic_epoch003=outputs/text_module_jepa_layerwise_gated_hsic_2m_4e/epoch_003.pt > $out/launcher_0.log 2>&1"
tmux new-session -d -s clevr_decomp_1 "cd $PWD && exec env CUDA_DEVICE_ORDER=PCI_BUS_ID CUDA_VISIBLE_DEVICES=1 PYTHONUNBUFFERED=1 $py evaluate_decomposed_representations.py --output-dir $out --checkpoint layerwise_no_hsic_epoch003=outputs/text_module_jepa_layerwise_no_hsic_2m_4e/epoch_003.pt --checkpoint layerwise_hsic_epoch003=outputs/text_module_jepa_layerwise_hsic_2m_4e/epoch_003.pt --checkpoint layerwise_gated_no_hsic_epoch003=outputs/text_module_jepa_layerwise_gated_no_hsic_2m_4e/epoch_003.pt > $out/launcher_1.log 2>&1"
tmux new-session -d -s clevr_decomp_2 "cd $PWD && exec env CUDA_DEVICE_ORDER=PCI_BUS_ID CUDA_VISIBLE_DEVICES=2 PYTHONUNBUFFERED=1 $py evaluate_decomposed_representations.py --output-dir $out --checkpoint avg_no_hsic_epoch003=outputs/text_module_jepa_avg_no_hsic_2m_4e/epoch_003.pt --checkpoint avg_hsic_epoch003=outputs/text_module_jepa_avg_hsic_2m_4e/epoch_003.pt --checkpoint avg_hsic_calibrated_old_epoch003=outputs/text_module_jepa_avg_hsic_calibrated_2m_4e/epoch_003.pt > $out/launcher_2.log 2>&1"
tmux new-session -d -s clevr_decomp_3 "cd $PWD && exec env CUDA_DEVICE_ORDER=PCI_BUS_ID CUDA_VISIBLE_DEVICES=3 PYTHONUNBUFFERED=1 $py evaluate_decomposed_representations.py --output-dir $out --checkpoint data2vec_avg_gated_epoch003=outputs/text_data2vec_avg_gated_shared_calibrated_jepa_hsic_2m_4e/epoch_003.pt --checkpoint data2vec_noavg_gated_epoch003=outputs/text_data2vec_noavg_gated_shared_calibrated_jepa_hsic_2m_4e/epoch_003.pt > $out/launcher_3.log 2>&1"
